<script setup>
import IncomeCharts from '../../Components/IncomeCharts.vue';
import { computed } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { money } from '../../Support/cart.js';
defineOptions({ layout: AppLayout });
const props = defineProps({ storeName: String, filters: Object, filterUrl: String, presets: Object, summary: Object, orders: Object });
const form = useForm({ ...props.filters });
const apply = () => form.get(props.filterUrl, { preserveState: true, preserveScroll: true, replace: true });
const preset = key => { form.from = props.presets[key]; form.to = props.presets.today; apply(); };
const date = value => new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Jakarta' }).format(new Date(value));
const cards = computed(() => [
    { title: 'Product sales', value: props.summary.productSales, note: `${props.summary.completedOrders} completed, paid orders` },
    { title: 'Delivery income', value: props.summary.deliverySales, note: 'From completed, paid orders' },
    { title: 'Payments received', value: props.summary.received, note: 'Cash retained + verified digital payments' },
    { title: 'Paid · In progress', value: props.summary.paidInProgress, note: 'Included in payments received' },
]);
const channels = computed(() => [
    { label: 'Cash retained', value: props.summary.cash }, { label: 'QRIS verified', value: props.summary.qris }, { label: 'Bank transfer verified', value: props.summary.bank_transfer },
    { label: 'Change returned', value: props.summary.changeReturned }, { label: 'Extra cash left by customers', value: props.summary.extraCash },
]);
</script>
<template>
<Head title="Income"/>
<div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs uppercase tracking-widest text-stone-500">{{ storeName }}</p><h1 class="mt-3 text-3xl font-semibold">Income</h1><p class="mt-3 text-sm text-stone-500">Sales and payments, clearly separated.</p></div><span class="rounded-full bg-white px-4 py-2 text-xs text-stone-500">WIB · Indonesian rupiah</span></div>
<form class="mt-7 rounded-2xl border border-stone-200 bg-white p-5" @submit.prevent="apply"><div class="mb-5 flex flex-wrap gap-2"><button v-for="(label,key) in { today: 'Today', week: 'This week', month: 'This month' }" :key="key" type="button" :disabled="form.processing" class="rounded-full border border-stone-200 px-4 py-2 text-sm hover:bg-stone-50 disabled:opacity-40" @click="preset(key)">{{ label }}</button></div><div class="grid items-end gap-4 sm:grid-cols-2 lg:grid-cols-4"><label class="text-sm">From<input v-model="form.from" required type="date" class="mt-2 w-full rounded-xl border border-stone-300 px-3 py-3"></label><label class="text-sm">To<input v-model="form.to" required type="date" :min="form.from" class="mt-2 w-full rounded-xl border border-stone-300 px-3 py-3"></label><label class="text-sm">Payment method<select v-model="form.payment" class="mt-2 w-full rounded-xl border border-stone-300 px-3 py-3"><option value="all">All methods</option><option value="cash">Cash</option><option value="qris">QRIS</option><option value="bank_transfer">Bank transfer</option></select></label><button :disabled="form.processing" class="rounded-full bg-[#504941] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40">{{ form.processing ? 'Loading…' : 'Apply filters' }}</button></div><p class="mt-4 text-xs leading-5 text-stone-500">Includes orders placed within these dates. Payments may have been received later.</p><p v-for="(error,key) in form.errors" :key="key" role="alert" class="mt-2 text-sm text-red-700">{{ error }}</p></form>
<section aria-label="Income summary" class="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><article v-for="card in cards" :key="card.title" class="rounded-2xl border border-stone-200 bg-[#fffdf9] p-5"><h2 class="text-sm text-stone-500">{{ card.title }}</h2><p class="mt-4 break-words text-2xl font-semibold tabular-nums">{{ money(card.value) }}</p><p class="mt-3 text-xs leading-5 text-stone-500">{{ card.note }}</p></article></section>
<IncomeCharts :summary="summary" :filters="filters"/><section class="mt-6 rounded-2xl border border-stone-200 bg-white p-5"><h2 class="font-semibold">Payment breakdown</h2><dl class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><div v-for="channel in channels" :key="channel.label"><dt class="text-xs text-stone-500">{{ channel.label }}</dt><dd class="mt-2 font-semibold tabular-nums">{{ money(channel.value) }}</dd></div></dl><p class="mt-5 border-t border-stone-100 pt-4 text-xs leading-6 text-stone-500">Extra cash is included in cash retained, separate from product sales. Returned change is excluded from payments received. Digital payments are shown before gateway fees; verification does not confirm payout to your bank. Gateway fees and payout balances are not available here yet. These figures are not profit.</p></section>
<section class="mt-8"><div class="flex items-center justify-between gap-3"><h2 class="text-xl font-semibold">Transactions</h2><span class="text-sm text-stone-500">{{ orders.total }} orders</span></div><div class="mt-4 overflow-x-auto rounded-2xl border border-stone-200 bg-white"><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-stone-50 text-xs text-stone-500"><tr><th class="p-4">Order / customer</th><th class="p-4">Payment</th><th class="p-4">Status</th><th class="p-4 text-right">Products</th><th class="p-4 text-right">Delivery</th><th class="p-4 text-right">Received</th></tr></thead><tbody class="divide-y divide-stone-100"><tr v-for="order in orders.data" :key="order.id"><td class="p-4"><Link :href="order.url" class="font-medium underline decoration-stone-300 underline-offset-4">{{ order.reference }}</Link><p class="mt-1">{{ order.customer_name }}</p><p class="mt-1 text-xs text-stone-500">{{ date(order.placedAt) }} WIB</p></td><td class="p-4"><p>{{ order.payment_method === 'cash' ? 'Cash' : order.payment_method === 'qris' ? 'QRIS' : 'Bank transfer' }}</p><p class="mt-2 text-xs" :class="order.payment_status === 'paid' ? 'text-green-800' : 'text-stone-500'">{{ order.payment_status === 'paid' ? 'Paid' : 'Unpaid' }}</p></td><td class="p-4 capitalize">{{ order.status.replaceAll('_',' ') }}</td><td class="p-4 text-right tabular-nums">{{ money(order.subtotal) }}</td><td class="p-4 text-right tabular-nums">{{ money(order.delivery_fee) }}</td><td class="p-4 text-right font-medium tabular-nums">{{ money(order.received) }}</td></tr><tr v-if="!orders.data.length"><td colspan="6" class="px-5 py-14 text-center text-stone-500">No orders in this period.</td></tr></tbody></table></div><nav v-if="orders.last_page > 1" aria-label="Transaction pages" class="mt-5 flex flex-wrap gap-2"><template v-for="(link,index) in orders.links" :key="index"><Link v-if="link.url" :href="link.url" :aria-current="link.active ? 'page' : undefined" class="rounded-lg border border-stone-200 px-3 py-2 text-sm" :class="link.active ? 'bg-[#504941] text-white' : 'bg-white'" preserve-scroll>{{ index === 0 ? 'Previous' : index === orders.links.length - 1 ? 'Next' : link.label }}</Link></template></nav></section>
</template>
